select jsonb_build_object(
'probeEntryId',(select id from public.meal_plan_entries where household_id='be772ffd-3ab5-41d5-8438-647a79a553da' and removed_at is null order by id limit 1),
'definitions',jsonb_build_object('count',(select count(*) from public.meal_definitions where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.meal_definitions r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'ingredients',jsonb_build_object('count',(select count(*) from public.meal_grocery_templates where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.meal_grocery_templates r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'entries',jsonb_build_object('count',(select count(*) from public.meal_plan_entries where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.meal_plan_entries r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'groceries',jsonb_build_object('count',(select count(*) from public.grocery_items where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.grocery_items r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'routines',jsonb_build_object('count',(select count(*) from public.routines where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.routines r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'occurrences',jsonb_build_object('count',(select count(*) from public.routine_occurrences where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.routine_occurrences r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'mealReceipts',jsonb_build_object('count',(select count(*) from public.meal_grocery_command_receipts where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by household_id,idempotency_key)::text,'null')) from public.meal_grocery_command_receipts r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'finance',jsonb_build_object('count',(select count(*) from public.financial_events where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.financial_events r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'ledger',jsonb_build_object('count',(select count(*) from public.ledger_entries where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by id)::text,'null')) from public.ledger_entries r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da')),
'allocations',jsonb_build_object('count',(select count(*) from public.financial_allocations where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'),'digest',(select md5(coalesce(jsonb_agg(to_jsonb(r) order by financial_event_id,member_id)::text,'null')) from public.financial_allocations r where household_id='be772ffd-3ab5-41d5-8438-647a79a553da'))
) as snapshot
